using System.Text.Json;
using System.Text;

if (args.Contains("--validate")) { Validation.Run(); return; }
var root = new DirectoryInfo(AppContext.BaseDirectory);
while (root != null && !File.Exists(Path.Combine(root.FullName, "src", "NDSharp.slnx"))) root = root.Parent;
if (root == null) throw new DirectoryNotFoundException("Run from a built repository checkout.");
var folder = Path.Combine(root.FullName, "src", "notebooks");
Directory.CreateDirectory(folder);
const string imports = "using System;\nusing System.Linq;\nusing System.IO;\nusing NDSharp;\nusing NDSharp.Frame;\nusing NDSharp.Plot;\nusing NDSharp.Image;\nusing NDSharp.Wavelets;\nusing SkiaSharp;\nusing FIndex = NDSharp.Frame.Index;\n";
var samples = new (string Slug, string Title, string Lesson, string Code)[]
{
    ("01-arrays", "Creating typed arrays", "Create a row-major 2 × 3 matrix. Inspect shape, dtype and size; explicit casts change storage precision.", "var a = np.Reshape(np.Arange(0L, 6L), 2, 3);\nConsole.WriteLine(a);\nConsole.WriteLine($\"shape={string.Join(\",\", a.Shape)}; dtype={a.DType}; size={a.Size}\");\nConsole.WriteLine(a.AsType(DType.Float32));\nif (a.Size != 6) throw new Exception(\"Unexpected size\");"),
    ("02-views", "Slicing and shared storage", "A basic slice shares its buffer with the original. Copy before editing if you need isolation. Strides are measured in elements, not bytes.", "var a = np.Reshape(np.Arange(0L, 12L), 3, 4);\nvar view = a.Get(new Slice(0, 2), new Slice(1, 3));\nConsole.WriteLine(view);\nConsole.WriteLine($\"Shared buffer: {ReferenceEquals(a.Buffer, view.Buffer)}\");\nConsole.WriteLine(np.Transpose(a));\nvar independent = view.Copy();\nif (ReferenceEquals(independent.Buffer, a.Buffer)) throw new Exception(\"Copy must own storage\");"),
    ("03-broadcasting", "Broadcasting and arithmetic", "A length-three vector is broadcast across two rows. Compatible trailing dimensions must match or be one.", "var a = np.Reshape(np.Arange(0L, 6L), 2, 3);\nvar offset = np.Arange(10L, 13L);\nvar result = np.Add(a, offset);\nConsole.WriteLine(result);\nConsole.WriteLine(np.Multiply(result, NDArray.Scalar(2L)));\nif (Convert.ToInt64(result[1, 2]) != 17L) throw new Exception(\"Broadcast mismatch\");"),
    ("04-reductions", "Reductions and descriptive statistics", "Reduce all elements or specify axes. keepdims preserves singleton dimensions for subsequent broadcasting.", "var a = np.Reshape(np.Arange(1L, 7L), 2, 3);\nConsole.WriteLine(np.Sum(a));\nConsole.WriteLine(np.Mean(a));\nConsole.WriteLine(np.Sum(a, axis: new[] { 1 }, keepdims: true));\nConsole.WriteLine(np.Median(a));\nif (Convert.ToInt64(np.Sum(a).GetAt(0)) != 21L) throw new Exception(\"Sum mismatch\");"),
    ("05-linear-algebra", "Solving a linear system", "Solve Ax=b rather than explicitly computing an inverse. Here A is diagonal, so the solution is [2, 3].", "var a = new NDArray(DType.Float64, new double[] { 2, 0, 0, 4 }, new[] { 2, 2 });\nvar b = new NDArray(DType.Float64, new double[] { 4, 12 }, new[] { 2 });\nvar x = np.Solve(a, b);\nConsole.WriteLine(x);\nConsole.WriteLine(np.Det(a));\nif (Math.Abs(Convert.ToDouble(x[1]) - 3) > 1e-10) throw new Exception(\"Solve mismatch\");"),
    ("06-random", "Reproducible random sampling", "Use a seeded Generator for repeatable results. Reusing a generator advances its stream; recreating it with the same seed restarts it.", "var seed = new System.Numerics.BigInteger[] { 42 };\nvar rng = NDSharp.Random.Generator.DefaultRng(seed);\nvar a = rng.Random(new[] { 2, 3 });\nConsole.WriteLine(a);\nConsole.WriteLine(rng.StandardNormal(new[] { 5 }));\nvar repeat = NDSharp.Random.Generator.DefaultRng(seed).Random(new[] { 2, 3 });\nif (!(bool)np.All(np.Equal(a, repeat)).GetAt(0)) throw new Exception(\"Seed mismatch\");"),
    ("07-signal", "FFT and signal differences", "Transform a small signal and invert it. FFT output is complex-valued. Diff computes adjacent differences, not a derivative scaled by sample spacing.", "var signal = new NDArray(DType.Float64, new double[] { 0, 1, 0, -1 }, new[] { 4 });\nvar spectrum = Fft.FFT(signal);\nConsole.WriteLine(spectrum);\nConsole.WriteLine(Fft.IFFT(spectrum));\nConsole.WriteLine(Fft.FFTFreq(4));\nConsole.WriteLine(np.Diff(signal));"),
    ("08-series", "Label alignment and missing values", "Series arithmetic aligns labels rather than row positions. Unmatched labels introduce missing values. Frame reductions skip missing values by default.", "var a = new Series(Column.FromLongs(new long[] { 1, 2 }), FIndex.OfStrings(new[] { \"x\", \"y\" }));\nvar b = new Series(Column.FromLongs(new long[] { 10, 20 }), FIndex.OfStrings(new[] { \"y\", \"z\" }));\nConsole.WriteLine(Formatter.SeriesRepr(Ops.Binary(BinOp.Add, a, b), new DisplayOptions()));\nvar values = Column.FromDoubles(new[] { 1.0, double.NaN, 3.0 });\nConsole.WriteLine(NDSharp.Frame.Reduce.Scalar(\"mean\", values));\nif (!Equals(NDSharp.Frame.Reduce.Scalar(\"count\", values), 2L)) throw new Exception(\"Missing count mismatch\");"),
    ("09-csv", "CSV to a DataFrame", "Csv.Read accepts CSV text, not a path. Pass the inferred names as the DataFrame column index. Use File.ReadAllText for a real file.", "var csv = \"city,value\\nParis,10\\nRome,20\\n\";\nvar (columns, names) = Csv.Read(csv, new Csv.ReadOptions());\nvar frame = new DataFrame(columns, FIndex.Of(names));\nConsole.WriteLine(Formatter.FrameRepr(frame));\nConsole.WriteLine(frame.GetColumn((object?)\"value\"));\nif (frame.NRows != 2) throw new Exception(\"Row count mismatch\");"),
    ("10-joins", "Outer joins", "Join two tables by key. An outer join retains both sets of keys; missing integer payloads are promoted to floating point.", "var left = new DataFrame(new[] { Column.FromLongs(new long[] { 1, 2 }), Column.FromLongs(new long[] { 10, 20 }) }, FIndex.OfStrings(new[] { \"key\", \"a\" }));\nvar right = new DataFrame(new[] { Column.FromLongs(new long[] { 2, 3 }), Column.FromLongs(new long[] { 5, 6 }) }, FIndex.OfStrings(new[] { \"key\", \"b\" }));\nvar joined = Merge.Join(left, right, new Merge.Spec { LeftOn = new object?[] { \"key\" }, RightOn = new object?[] { \"key\" }, How = \"outer\" });\nConsole.WriteLine(Formatter.FrameRepr(joined));\nif (joined.NRows != 3) throw new Exception(\"Join mismatch\");"),
    ("11-line-plot", "Rendering a line plot", "Plotting uses SkiaSharp native assets. RenderPng returns bytes; this notebook saves a PNG in the kernel working directory.", "var figure = new Figure();\nvar axes = figure.AddAxes(GridCell.Single(1, 1, 0));\naxes.Add(new Line2D(new double[] { 0, 1, 2, 3 }, new double[] { 0, 1, 4, 9 }, SKColors.Blue));\nvar png = figure.RenderPng();\nFile.WriteAllBytes(\"ndsharp-line.png\", png);\nConsole.WriteLine(Path.GetFullPath(\"ndsharp-line.png\"));\nif (png[0] != 0x89) throw new Exception(\"PNG mismatch\");"),
    ("12-heatmap", "Heatmaps and colorbars", "ImageArtist maps numeric values through a named colormap. AddColorbar attaches a scale to a mappable artist.", "var figure = new Figure();\nvar axes = figure.AddAxes(GridCell.Single(1, 1, 0));\nvar image = new ImageArtist { Rows = 2, Cols = 3, Values = new double[] { 0, 1, 2, 3, 4, 5 }, Cmap = Colormap.Get(\"viridis\") };\naxes.Add(image);\nfigure.AddColorbar(image, label: \"value\");\nFile.WriteAllBytes(\"ndsharp-heatmap.png\", figure.RenderPng());\nConsole.WriteLine(Path.GetFullPath(\"ndsharp-heatmap.png\"));"),
    ("13-image", "OpenCV array conversions", "Requires the Windows OpenCV native runtime supplied by NDSharp.Image, or a compatible native deployment on another OS. Image layout is height × width × channels; OpenCV uses BGR order.", "var bgr = np.Full(new[] { 2, 2, 3 }, 100L, DType.UInt8);\nvar gray = Cv.CvtColor(bgr, 6); // OpenCV COLOR_BGR2GRAY\nConsole.WriteLine(gray);\nusing var mat = Mats.ToMat(gray);\nvar restored = Mats.FromMat(mat);\nif (!(bool)np.All(np.Equal(gray, restored)).GetAt(0)) throw new Exception(\"Mat roundtrip mismatch\");"),
    ("14-wavelets", "Wavelet decomposition and reconstruction", "A single Haar transform separates approximation and detail coefficients. Use the same wavelet and boundary mode for reconstruction. Odd input lengths can require trimming the reconstructed signal.", "var signal = new double[] { 1, 2, 3, 4, 5, 6, 7, 8 };\nvar wavelet = Wavelet.Get(\"haar\");\nvar (approximation, detail) = Dwt.Dwt1D(signal, wavelet);\nConsole.WriteLine(string.Join(\", \", approximation));\nConsole.WriteLine(string.Join(\", \", detail));\nvar restored = Dwt.Idwt1D(approximation, detail, wavelet);\nif (signal.Zip(restored).Any(p => Math.Abs(p.First - p.Second) > 1e-10)) throw new Exception(\"Wavelet roundtrip mismatch\");")
};
var validation = new StringBuilder("#nullable enable\n" + imports).AppendLine("public static class Validation { public static void Run() {");
for (int i = 0; i < samples.Length; i++) validation.AppendLine($"Sample{i}(); Console.WriteLine(\"PASS {samples[i].Slug}\");");
validation.AppendLine("}");
foreach (var (sample, i) in samples.Select((s, i) => (s, i)))
{
    object Markdown(string text) => new { cell_type = "markdown", metadata = new { }, source = new[] { text } };
    object Code(string text) => new { cell_type = "code", execution_count = (int?)null, metadata = new { dotnet_interactive = new { language = "csharp" }, polyglot_notebook = new { kernelName = "csharp" } }, outputs = Array.Empty<object>(), source = new[] { text } };
    var notebook = new
    {
        cells = new[] { Markdown($"# {sample.Title}\n\n{sample.Lesson}\n\nRun cells top to bottom with the .NET Interactive C# kernel. See ../../USAGE.md for package-feed setup."), Code($"#r \"nuget: NDSharp, {PackageVersions.NDSharp}\"\n#r \"nuget: NDSharp.Frame, {PackageVersions.Frame}\"\n#r \"nuget: NDSharp.Plot, {PackageVersions.Plot}\"\n#r \"nuget: NDSharp.Image, {PackageVersions.Image}\"\n#r \"nuget: NDSharp.Wavelets, {PackageVersions.Wavelets}\"\n" + imports), Code(sample.Code), Markdown("## Try it\n\nChange the input size or values and rerun the example. Predict the new shape or result first. Restart the kernel and Run All to verify that the notebook is self-contained.") },
        metadata = new { kernelspec = new { display_name = ".NET (C#)", language = "C#", name = ".net-csharp" }, language_info = new { name = "C#" }, polyglot_notebook = new { kernelInfo = new { defaultKernelName = "csharp", items = new[] { new { name = "csharp", languageName = "C#", aliases = new[] { "c#", "C#" } } } } } },
        nbformat = 4, nbformat_minor = 4
    };
    File.WriteAllText(Path.Combine(folder, sample.Slug + ".ipynb"), JsonSerializer.Serialize(notebook, new JsonSerializerOptions { WriteIndented = true }));
    validation.AppendLine($"public static void Sample{i}() {{\n{sample.Code}\n}}");
}
validation.AppendLine("}");
File.WriteAllText(Path.Combine(root.FullName, "src", "NDSharp.Notebooks", "Validation.g.cs"), validation.ToString());
Console.WriteLine($"Generated {samples.Length} notebooks and their compiled validation companion.");

// Package versions the notebooks restore with #r "nuget: ...". They come from the local feed (D:\Dev\NuGetLocalFeed): no NDSharp package is on
// nuget.org. Move them when the feed moves on, then regenerate (see USAGE.md) and run the gate step ndsharp-notebooks.
static class PackageVersions
{
    public const string NDSharp = "2.8.1-net11-preview.1";
    public const string Frame = "2.5.1-net11-preview.1";
    public const string Plot = "2.6.3-net11-preview.2";
    public const string Image = "2.5.1-net11-preview.1";
    public const string Wavelets = "2.5.1-net11-preview.1";
}
